style.css:
@-moz-document domain("youtube.com") {
body {
    background: url("https://your-image-link.com/invincible-bg.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  ytd-watch-flexy, ytd-masthead, ytd-mini-guide-renderer, tp-yt-app-drawer {
    background: rgba(0, 0, 0, 0.65) !important;
    border-radius: 12px !important;
  }

  * {
    font-family: 'Orbitron', sans-serif !important;
    color: #f0f0f0 !important;
  }

  h1.title {
    color: #FFD700 !important;
    text-shadow: 0 0 5px black;
  }

  ytd-playlist-panel-renderer {
    background-color: rgba(10, 10, 10, 0.8) !important;
    border-left: 3px solid #FFD700 !important;
  }

  ytd-toggle-button-renderer, ytd-button-renderer {
    background-color: rgba(255, 255, 255, 0.1) !important;
    border-radius: 8px !important;
    transition: 0.3s ease;
  }

  ytd-toggle-button-renderer:hover, ytd-button-renderer:hover {
    background-color: #FFD700 !important;
    color: black !important;
  }
}
